-- 线性表进阶：双向链接的成对不变量。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '双链表','双链表结点同时保存 prev 与 next；更新时必须保持相邻结点的正反向指针一致。',course.id,parent.id,'cs408-doubly-linked-list','AISTU',1,'REVIEWED',6,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-linear-lists' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-doubly-linked-list' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-doubly-linked-list',1,'REVIEWED','双链表',JSON_OBJECT('summary','双链表的每个结点保存 prev、数据和 next。局部插删能直接访问前驱和后继，但每次改接都要保持成对不变量：若 p.next=q，则 q.prev=p；额外指针也带来空间开销。','steps',JSON_ARRAY('结点同时记录前驱与后继入口','插入时连接新结点两侧的四条相关指针','删除时让目标两侧重新互指','逐一检查 next 与 prev 是否成对一致'),'prerequisite',JSON_OBJECT('contentKey','cs408-linked-list-insert-delete','title','链表结点的插入与删除','description','先掌握单向链表中保留链路的赋值顺序。'),'nextStep',JSON_OBJECT('contentKey','cs408-circular-linked-list','title','循环链表','description','继续学习不以 null 作为终止标记的链式表示。')),JSON_OBJECT('id','doubly-linked-list-v1','prompt','双链表中已知 p.next = q 时，必须同时满足什么不变量？','options',JSON_ARRAY(JSON_OBJECT('id','PAIR_INVARIANTS','text','q.prev = p，正反向指针彼此对应'),JSON_OBJECT('id','SAME_DATA','text','p 与 q 的数据域必须保存相同值')),'correctOptionId','PAIR_INVARIANTS','correctExplanation','正确：双链表的相邻结点必须通过 next 与 prev 形成一致的双向连接。','incorrectExplanation','不正确：数据值不决定链表的链接关系。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-doubly-linked-list' AND existing.content_version=1 WHERE point.content_key='cs408-doubly-linked-list' AND existing.id IS NULL;
